{
  "name": "集群数据流传输器",
  "name_en": "Cluster Data Streamer",
  "manufacturer": "",
  "description": "用于实验数据处理流程的非实体软件组件。它通过异步、非阻塞方式将文件或数据块排队并持续发送到单一服务器或集群节点，适合采集过程中进行后台流式写入与收尾归档。",
  "description_en": "A non-physical software component for experimental data workflows. It queues files or data blocks and streams them asynchronously in a non-blocking manner to a single server or cluster nodes, supporting background data spooling and finalization during acquisition.",
  "actions": [
    {
      "action_name": "auto-finalize",
      "description": "完成数据流传输并执行收尾，可选择写入结束标记文件后停止相关线程。",
      "description_en": "Finalize the data stream and perform cleanup, optionally writing a sentinel file before stopping the related threads."
    },
    {
      "action_name": "auto-close",
      "description": "关闭传输器并停止后台活动。",
      "description_en": "Close the streamer and stop background activity."
    },
    {
      "action_name": "auto-put",
      "description": "将文件或数据加入发送队列进行异步传输；传入空数据可作为结束标记。",
      "description_en": "Queue a file or data block for asynchronous transfer; passing null data can act as an end-of-stream sentinel."
    }
  ],
  "tag_hints": [
    "asynchronous data streaming",
    "non-blocking file spooling",
    "cluster data transfer",
    "experiment data pipeline",
    "persistent server connection",
    "background upload"
  ]
}

